insert into lhq_labels (key, locale, value) values
('DASH_EDGE_SETUP_TIP','en','Squeeze score: funding rate (0–40 pts) + long/short share, Bybit accounts (0–40 pts) + taker buy/sell pressure over 2 hours (0–15 pts) + volume spike bonus (0–20 pts). Long-heavy = funding positive and most accounts long. Short-heavy = funding negative and most accounts short. It describes positioning; it does not forecast price.'),
('DASH_EDGE_SETUP_TIP','ko','스퀴즈 점수: 펀딩비 (0–40점) + 롱/숏 비중, 바이비트 계정 기준 (0–40점) + 2시간 테이커 매수/매도 압력 (0–15점) + 거래량 급증 가산점 (0–20점). 롱 쏠림 = 펀딩 양수이고 대부분의 계정이 롱. 숏 쏠림 = 펀딩 음수이고 대부분의 계정이 숏. 포지셔닝을 설명할 뿐 가격을 예측하지 않습니다.'),
('DASH_EDGE_SETUP_TIP','zh','挤压分数：资金费率（0–40 分）+ 多空占比，Bybit 账户（0–40 分）+ 2 小时吃单买卖压力（0–15 分）+ 成交量激增加分（0–20 分）。多头拥挤 = 资金费率为正且多数账户做多。空头拥挤 = 资金费率为负且多数账户做空。它描述仓位情况，不预测价格。'),
('DASH_EDGE_SETUP_TIP','ru','Балл сквиза: ставка фандинга (0–40) + доля лонг/шорт по аккаунтам Bybit (0–40) + давление тейкеров за 2 часа (0–15) + бонус за всплеск объёма (0–20). Перекос в лонги = фандинг положительный и большинство аккаунтов в лонге. Перекос в шорты = фандинг отрицательный и большинство в шорте. Описывает позиционирование, а не прогноз цены.'),
('DASH_EDGE_SETUP_TIP','ar','درجة الانضغاط: معدل التمويل (0–40) + نسبة الشراء/البيع حسب حسابات Bybit (0–40) + ضغط الشراء/البيع لدى التيكر خلال ساعتين (0–15) + مكافأة ارتفاع الحجم (0–20). ميل للشراء = تمويل موجب ومعظم الحسابات شراء. ميل للبيع = تمويل سالب ومعظم الحسابات بيع. تصف التمركز ولا تتنبأ بالسعر.'),
('SETUP_SCANNER_LEGEND_FOOTER','en','Score 0–100: funding (0–40) + long/short share, Bybit accounts (0–40) + taker flow, 2 h (0–15) + volume spike (0–20)'),
('SETUP_SCANNER_LEGEND_FOOTER','ko','점수 0–100: 펀딩 (0–40) + 롱/숏 비중, 바이비트 계정 기준 (0–40) + 테이커 흐름 2시간 (0–15) + 거래량 급증 (0–20)'),
('SETUP_SCANNER_LEGEND_FOOTER','zh','分数 0–100：资金费率 (0–40) + 多空占比，Bybit 账户 (0–40) + 吃单流量 2 小时 (0–15) + 成交量激增 (0–20)'),
('SETUP_SCANNER_LEGEND_FOOTER','ru','Балл 0–100: фандинг (0–40) + доля лонг/шорт по аккаунтам Bybit (0–40) + поток тейкеров, 2 ч (0–15) + всплеск объёма (0–20)'),
('SETUP_SCANNER_LEGEND_FOOTER','ar','الدرجة 0–100: التمويل (0–40) + نسبة الشراء/البيع حسب حسابات Bybit (0–40) + تدفق التيكر، ساعتان (0–15) + ارتفاع الحجم (0–20)'),
('DASH_EDGE_SETUP_DETAIL_LONG_SHARE','en','long share {pct}% ({venue}, accounts, 1h)'),
('DASH_EDGE_SETUP_DETAIL_LONG_SHARE','ko','롱 비중 {pct}% ({venue}, 계정, 1시간)'),
('DASH_EDGE_SETUP_DETAIL_LONG_SHARE','zh','多头占比 {pct}%（{venue}，账户，1 小时）'),
('DASH_EDGE_SETUP_DETAIL_LONG_SHARE','ru','доля лонгов {pct}% ({venue}, аккаунты, 1ч)'),
('DASH_EDGE_SETUP_DETAIL_LONG_SHARE','ar','حصة الشراء {pct}% ({venue}، الحسابات، 1س)'),
('DASH_EDGE_SETUP_DETAIL_SHORT_SHARE','en','short share {pct}% ({venue}, accounts, 1h)'),
('DASH_EDGE_SETUP_DETAIL_SHORT_SHARE','ko','숏 비중 {pct}% ({venue}, 계정, 1시간)'),
('DASH_EDGE_SETUP_DETAIL_SHORT_SHARE','zh','空头占比 {pct}%（{venue}，账户，1 小时）'),
('DASH_EDGE_SETUP_DETAIL_SHORT_SHARE','ru','доля шортов {pct}% ({venue}, аккаунты, 1ч)'),
('DASH_EDGE_SETUP_DETAIL_SHORT_SHARE','ar','حصة البيع {pct}% ({venue}، الحسابات، 1س)'),
('BTC_RISK_LEVEL_TITLE','en','BTC Crowding (sentiment + funding)'),
('BTC_RISK_LEVEL_TITLE','ko','BTC 쏠림 (심리 + 펀딩)'),
('BTC_RISK_LEVEL_TITLE','zh','BTC 拥挤度（情绪 + 资金费率）'),
('BTC_RISK_LEVEL_TITLE','ru','Перегрев BTC (настроения + фандинг)'),
('BTC_RISK_LEVEL_TITLE','ar','ازدحام BTC (المعنويات + التمويل)'),
('BTC_RISK_LEVEL_TOOLTIP','en','Blends three inputs into one 0-100 score of how crowded long positions look: the Fear & Greed index, BTC''s daily RSI, and BTC''s funding rate (only positive funding adds to it). It does not use the long/short account ratio. It describes positioning, not a forecast of price.'),
('BTC_RISK_LEVEL_TOOLTIP','ko','세 가지 입력을 0-100 점수 하나로 합쳐 롱 포지션이 얼마나 쏠려 있는지 보여줍니다: 공포·탐욕 지수, BTC 일봉 RSI, BTC 펀딩비(양수 펀딩만 반영). 롱/숏 계정 비율은 사용하지 않습니다. 포지셔닝을 설명할 뿐 가격 예측이 아닙니다.'),
('BTC_RISK_LEVEL_TOOLTIP','zh','将三个输入合成一个 0-100 分数，表示多头仓位的拥挤程度：恐惧与贪婪指数、BTC 日线 RSI 和 BTC 资金费率（仅正资金费率计入）。不使用多空账户比。它描述仓位情况，而非价格预测。'),
('BTC_RISK_LEVEL_TOOLTIP','ru','Объединяет три входа в одну оценку 0-100 того, насколько переполнены лонги: индекс страха и жадности, дневной RSI BTC и фандинг BTC (учитывается только положительный). Соотношение лонг/шорт аккаунтов не используется. Описывает позиционирование, а не прогноз цены.'),
('BTC_RISK_LEVEL_TOOLTIP','ar','يجمع ثلاثة مدخلات في درجة 0-100 توضح مدى ازدحام المراكز الطويلة: مؤشر الخوف والطمع وRSI اليومي لـ BTC ومعدل تمويل BTC (التمويل الموجب فقط يُحتسب). لا يستخدم نسبة حسابات الشراء/البيع. يصف التمركز وليس توقعًا للسعر.'),
('MARKET_CONDITIONS_WIDGET_LONG_SHORT_LABEL','en','BTC long / short · Binance, all accounts, 1h'),
('MARKET_CONDITIONS_WIDGET_LONG_SHORT_LABEL','ko','BTC 롱 / 숏 · 바이낸스, 전체 계정, 1시간'),
('MARKET_CONDITIONS_WIDGET_LONG_SHORT_LABEL','zh','BTC 多 / 空 · 币安，全部账户，1 小时'),
('MARKET_CONDITIONS_WIDGET_LONG_SHORT_LABEL','ru','BTC лонг / шорт · Binance, все аккаунты, 1ч'),
('MARKET_CONDITIONS_WIDGET_LONG_SHORT_LABEL','ar','BTC شراء / بيع · Binance، كل الحسابات، 1س'),
